          durata: apt.durata,
          tipologia: apt.tipoIntervento,
          note: apt.note,
          stato: apt.stato,
        }),
      });
      const body = (await res.json().catch(() => ({}))) as {
        error?: { kind?: string; message?: string };
      } & Record<string, unknown>;
      if (res.status === 409)
        return body.error?.message ?? 'Slot già occupato: scegli un altro orario.';
