  // ── Therapy CRUD (API-persisted with optimistic update) ─────────────────────

  async function confirmTherapy(info: TherapyActionInfo) {
    const now = new Date();
    setTherapySlots((prev) =>
      prev.map((slot) => {
        if (slot.fascia !== info.fascia) return slot;
        return {
          ...slot,
          summary: {
            ...slot.summary,
            administered: slot.summary.administered + 1,
            pending: Math.max(0, slot.summary.pending - 1),
          },
          patients: slot.patients.map((p: TherapySlotPatient) => {
            if (p.patientId !== info.patientId) return p;
            return {
              ...p,
              administrations: p.administrations.map((a: TherapyAdministration) =>
                a.therapyId === info.therapyId
                  ? {
                      ...a,
                      status: 'administered' as const,
                      administeredAt: now.toISOString(),
                      administeredBy: utente?.nome ?? '',
                    }
                  : a,
              ),
            };
          }),
        };
      }),
    );

    try {
      const res = await fetch(`${API_URL}/therapy-slots/confirm`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...operatorHeaders() },
        body: JSON.stringify({
          patientId: info.patientId,
          farmacoNome: info.drugName,
          farmacoDose: info.dosage,
          farmacoVia: info.route,
          date: info.date,
          fascia: info.fascia,
          ora: info.ora,
          operatoreId: utente?.id ?? '',
          operatoreNome: utente?.nome ?? '',
          therapyId: info.therapyId,
        }),
      });

      if (res.status === 409) {
        showToast('Terapia già erogata');
        loadTherapySlots(info.date);
        return;
      }
      if (res.ok) {
        showToast('Somministrazione confermata');
        loadTherapySlots(info.date);
      } else {
        showToast('Errore durante conferma');
        loadTherapySlots(info.date);
      }
    } catch {
      showToast('Errore di rete');
      loadTherapySlots(info.date);
    } finally {
      invalidateCachedGet(`${API_URL}/therapy-slots`);
    }
  }

  async function notAdministeredTherapy(
    info: TherapyActionInfo,
    motivo: MotivoNonErogazione,
    noteText: string,
  ) {
    setTherapySlots((prev) =>
      prev.map((slot) => {
        if (slot.fascia !== info.fascia) return slot;
        return {
          ...slot,
          summary: {
            ...slot.summary,
            notAdministered: slot.summary.notAdministered + 1,
            pending: Math.max(0, slot.summary.pending - 1),
          },
          patients: slot.patients.map((p: TherapySlotPatient) => {
            if (p.patientId !== info.patientId) return p;
            return {
              ...p,
              administrations: p.administrations.map((a: TherapyAdministration) =>
                a.therapyId === info.therapyId
                  ? { ...a, status: 'not_administered' as const, notAdministeredReason: motivo }
                  : a,
              ),
            };
          }),
        };
      }),
    );

    try {
      const res = await fetch(`${API_URL}/therapy-slots/not-administered`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...operatorHeaders() },
        body: JSON.stringify({
          patientId: info.patientId,
          farmacoNome: info.drugName,
          farmacoDose: info.dosage,
          farmacoVia: info.route,
          date: info.date,
          fascia: info.fascia,
          ora: info.ora,
          operatoreId: utente?.id ?? '',
          operatoreNome: utente?.nome ?? '',
          therapyId: info.therapyId,
          motivo,
          note: noteText,
        }),
      });

      if (res.ok) {
        showToast('Non somministrazione registrata');
        loadTherapySlots(info.date);
      } else {
        showToast('Errore durante registrazione');
        loadTherapySlots(info.date);
      }
    } catch {
      showToast('Errore di rete');
      loadTherapySlots(info.date);
    } finally {
      invalidateCachedGet(`${API_URL}/therapy-slots`);
    }
  }

  // ── Search ──────────────────────────────────────────────────────────────────

  const globalPatientSearch = usePatientDirectorySearch(searchQuery, {
    enabled: searchOpen,
    limit: 6,
  });
  const searchResults = globalPatientSearch.results;

  const utenteId = utente?.id ?? '';
  const isAdmin = utente?.ruolo === 'admin';

  // ── Login gate ──────────────────────────────────────────────────────────────

  if (!utente)
    return (
      <Login
        onLogin={handleLogin}
        demoMode={authStatus?.temporaryDemo === true}
        loading={loginPending}
        error={loginError}
      />
    );

  // ── Render ───────────────────────────────────────────────────────────────────

  return (
    <RosterOrderContext.Provider value={rosterOrder}>
    <div className={`app-shell${mobileNavOpen ? ' app-shell--nav-open' : ''}`}>
      {/* Scrim per il drawer di navigazione mobile (≤1023px) */}
      {mobileNavOpen && (
        <div
          className="mobile-nav-scrim"
          onClick={() => setMobileNavOpen(false)}
          aria-hidden="true"
        />
      )}
      {toastMsg && (
        <div className="app-toast app-toast--success" role="status">
          <svg
            width="16"
            height="16"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <polyline points="20 6 9 17 4 12" />
          </svg>
          <span>{toastMsg}</span>
          <button
            className="app-toast__close"
            onClick={() => setToastMsg(null)}
            aria-label="Chiudi"
          >
            ×
          </button>
        </div>
      )}

      {/* Teams-style sidebar */}
      <TeamsLikeSidebar
        activeKey={navKey}
        utente={utente}
        onNavigate={(k) => navigate(k)}
        onLogout={handleLogout}
        unreadNotes={notesUnreadCount}
      />

      {/* Main */}
      <div className="main-area-clean">
        {authStatus?.temporaryDemo && (
          <div className="demo-mode-chip" role="status">
            <strong>DEMO</strong>
            <span>Solo dati sintetici · azioni persistenti</span>
          </div>
        )}
        {/* Compact Topbar */}
        <div className="compact-topbar">
          <button
            type="button"
            className="topbar-hamburger"
            onClick={() => setMobileNavOpen((v) => !v)}
            aria-label={mobileNavOpen ? 'Chiudi menu' : 'Apri menu'}
            aria-expanded={mobileNavOpen}
          >
            <svg
              width="22"
              height="22"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
            >
              <line x1="3" y1="6" x2="21" y2="6" />
              <line x1="3" y1="12" x2="21" y2="12" />
              <line x1="3" y1="18" x2="21" y2="18" />
            </svg>
          </button>
          <button
            type="button"
            className="topbar-search"
            onClick={() => setSearchOpen(true)}
            title="Cerca (Ctrl+K)"
          >
            <IcoSearch />
            <span className="topbar-search__ph">Cerca paziente, camera, codice fiscale…</span>
            <kbd className="topbar-search__kbd">/</kbd>
          </button>
          {utente && (
            <div className="topbar-ctx">
              <span className="topbar-shift">
                <span className="topbar-shift__dot" aria-hidden="true" />
                {utente.reparto}
              </span>
              <div className="topbar-user">
                <span className="topbar-user__avatar" aria-hidden="true">
                  {utente.iniziali}
                </span>
                <span className="topbar-user__meta">
                  <span className="topbar-user__name">{utente.nome}</span>
                  <span className="topbar-user__role">
                    {utente.ruolo === 'admin' ? 'Amministratore' : 'Operatore'}
                  </span>
                </span>
              </div>
            </div>
          )}
        </div>

        {/* Search overlay */}
        {searchOpen && (
          <div className="search-overlay" onClick={() => setSearchOpen(false)}>
            <div className="search-modal" onClick={(e) => e.stopPropagation()}>
              <div className="search-modal__input-wrap">
                <IcoSearch />
                <input
                  ref={searchRef}
                  className="search-modal__input"
                  type="search"
                  placeholder="Cerca paziente per nome o codice fiscale…"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  maxLength={80}
                />
                <button className="icon-btn" onClick={() => setSearchOpen(false)}>
                  <IcoX />
                </button>
              </div>
              {searchResults.length > 0 && (
                <ul className="search-modal__results">
                  {searchResults.map((p) => (
                    <li key={p.id}>
                      <button
                        className="search-modal__result-item"
                        onClick={() => {
                          selectPaziente(p);
                          setSearchOpen(false);
                          setSearchQuery('');
                        }}
                      >
                        <span
                          className="op-avatar-sm"
                          style={{ width: 32, height: 32, fontSize: 12 }}
                          aria-hidden="true"
                        >
                          {p.firstName[0]}
                          {p.lastName[0]}
                        </span>
                        <div>
                          <span className="search-result__name">
                            {p.lastName}, {p.firstName}
                          </span>
                          <span className="search-result__cf">
                            {p.codiceFiscale ?? 'Codice fiscale non disponibile'}
                          </span>
                        </div>
                      </button>
                    </li>
                  ))}
                </ul>
              )}
              {globalPatientSearch.loading && (
                <p className="search-modal__empty" role="status">
                  Ricerca in corso…
                </p>
              )}
              {globalPatientSearch.error && (
                <p className="search-modal__empty" role="alert">
                  {globalPatientSearch.error}
                </p>
              )}
              {searchQuery.trim().length > 1 &&
                !globalPatientSearch.loading &&
                !globalPatientSearch.error &&
                searchResults.length === 0 && (
                  <p className="search-modal__empty">Nessun paziente trovato.</p>
                )}
            </div>
          </div>
        )}

        {/* Page content */}
        <main className="page-content content-panel">
          <LazyLoadBoundary>
            <Suspense fallback={<PageLoading />}>
              {needsOperatorDirectory &&
              operatori.length === 0 &&
              (operatorDirectoryLoadState === 'idle' ||
                operatorDirectoryLoadState === 'loading') ? (
                <PageLoading />
              ) : needsOperatorDirectory &&
                operatori.length === 0 &&
                operatorDirectoryLoadState === 'error' ? (
                <div className="load-error-state" role="alert">
                  <p>{operatorDirectoryLoadError}</p>
                  <button
                    type="button"
                    className="btn-secondary"
                    onClick={() => void loadOperatorDirectory(true)}
                  >
                    Riprova
                  </button>
                </div>
              ) : (
                <>
                  {needsOperatorDirectory &&
                    operatori.length > 0 &&
                    operatorDirectoryLoadState === 'error' && (
                      <div className="load-error-state" role="alert">
                        <p>
                          {operatorDirectoryLoadError} Sono mostrati gli ultimi dati disponibili.
                        </p>
                        <button
                          type="button"
                          className="btn-secondary"
                          onClick={() =>
                            void loadOperatorDirectory(
                              !operatorDirectoryRetryCursor,
                              operatorDirectoryRetryCursor,
                            )
                          }
                        >
                          Riprova
                        </button>
                      </div>
                    )}
                  {needsOperatorDirectory &&
                    operatori.length > 0 &&
                    operatorDirectoryPageInfo.hasMore &&
                    operatorDirectoryPageInfo.nextCursor && (
                      <div className="cdt__pagination" role="status">
                        <span>{operatori.length} operatori caricati</span>
                        <button
                          type="button"
                          className="btn-ghost-outline"
                          disabled={operatorDirectoryLoadState === 'loading'}
                          onClick={() =>
                            void loadOperatorDirectory(false, operatorDirectoryPageInfo.nextCursor)
                          }
                        >
                          {operatorDirectoryLoadState === 'loading'
                            ? 'Caricamento…'
                            : 'Carica altri operatori'}
                        </button>
                      </div>
                    )}
                  {/* ── ADMIN ── */}
                  {isAdmin && navKey === 'admin-dashboard' && (
                    <AdminDashboard
                      operatori={operatori}
                      operatorSummary={operatorDirectorySummary}
                      consegneOverview={consegneOverview}
                      consegneOverviewState={consegneOverviewState}
                      camere={camere}
                      camereLoadState={camereLoadState}
                      camereLoadError={camereLoadError}
                      onRetryCamere={() => void loadCamere(true)}
                      totalePazienti={clinicalOverview?.totalPatients ?? 0}
                      loadingPazienti={loadingClinicalOverview}
                      onNavigate={navigate}
                      onOpenConsegneAperte={openConsegneAperte}
                      onOpenConsegneFeed={() => openConsegneFeed()}
                      onSelectPaziente={goToPazienteByNome}
                      clinicalOverview={clinicalOverview}
                      clinicalOverviewState={clinicalOverviewState}
                      onRetryClinicalOverview={() => void loadClinicalOverview()}
                    />
                  )}
                  {isAdmin && navKey === 'gestione-operatori' && (
                    <OperatorManagement
                      operatori={operatori}
                      summary={operatorDirectorySummary}
                      onSearch={searchOperatorDirectory}
                      onStatusChange={filterOperatorDirectoryByStatus}
                      onAdd={addOperatore}
                      onUpdate={updateOperatore}
                      onToggleStato={toggleStatoOperatore}
                    />
                  )}
                  {isAdmin && navKey === 'agenda-admin' && (
                    <AdminAgenda
                      operatori={operatori}
                      appuntamenti={appuntamenti}
                      onAddAppuntamento={addAppuntamento}
                      onUpdateAppuntamento={updateAppuntamento}
                      onDeleteAppuntamento={deleteAppuntamento}
                      loadingAppuntamenti={loadingAppuntamenti}
                      appointmentLoadError={appointmentLoadError}
                      onRetryAppointments={retryAppointmentRange}
                      onLoadAppointments={loadAppointmentRange}
                      onAddPaziente={() => {}}
                      onSelectPaziente={goToPazienteByNome}
                    />
                  )}
                  {isAdmin && navKey === 'posti-letto' && <RoomsManagement />}
                  {isAdmin && navKey === 'orari-operatori' && (
                    <OperatorSchedule
                      operatori={operatori}
                      schedules={schedules}
                      loadState={schedulesLoadState}
                      loadError={schedulesLoadError}
                      onRetry={() => void loadSchedules(true)}
                      onSave={saveSchedule}
                    />
                  )}

                  {/* ── SHARED ── */}
                  {navKey === 'terapie' && (
                    <TherapyRoundsPage
                      slots={therapySlots}
                      loading={loadingTherapySlots}
                      error={therapyLoadError}
                      pageInfo={therapyPageInfo}
                      loadingMore={loadingMoreTherapySlots}
                      loadMoreError={therapyLoadMoreError}
                      onLoad={loadTherapySlots}
                      onLoadMore={loadMoreTherapySlots}
                      readOnly={isAdmin}
                      onConfirm={confirmTherapy}
                      onNotAdministered={notAdministeredTherapy}
                    />
                  )}
                  {navKey === 'consegne' && (
                    <ConsegneWorkspace
                      sessionKey={utenteId}
                      entry={consegneView}
                      draftStore={consegnaDraftStore}
                      onModeChange={setConsegneMode}
                      consegne={consegne}
                      summary={consegneSummary}
                      operatori={operatori}
                      operatoreId={utenteId}
                      isAdmin={isAdmin}
                      onAdd={addConsegna}
                      onUpdate={updateConsegna}
                      onUpdateStato={updateConsegnaStato}
                      onDelete={deleteConsegna}
                      loading={loadingConsegne}
                      loadError={consegneLoadError}
                      hasMore={consegnePageInfo.hasMore}
                      onQueryChange={loadConsegne}
                      onLoadMore={() => void loadConsegne(consegneQueryRef.current, true)}
                      onRetry={() => void loadConsegne(consegneQueryRef.current)}
                      onSelectPaziente={goToPazienteByNome}
                      initialFiltroStato={consegneView.query?.status}
                      focusId={consegneView.focusId}
                    />
                  )}
                  {navKey === 'note' && (
                    <NotesPage
                      note={note}
                      utenteId={utenteId}
                      isAdmin={isAdmin}
                      operatori={operatori}
                      loading={loadingNotes}
                      loadError={notesLoadError}
                      unreadCount={notesUnreadCount}
                      hasMore={notesPageInfo.hasMore}
                      onAdd={addNota}
                      onUpdate={updateNota}
                      onUpdateStato={updateNotaStato}
                      onQueryChange={loadNotes}
                      onLoadMore={() => void loadNotes(notesQueryRef.current, true)}
                      onRetry={() => void loadNotes(notesQueryRef.current)}
                    />
                  )}

                  {/* ── OPERATOR ── */}
                  {!isAdmin && navKey === 'operator-dashboard' && (
                    <OperatorDashboard
                      utente={utente}
                      consegneOverview={consegneOverview}
                      consegneOverviewState={consegneOverviewState}
                      agenda={agendaOggi}
                      onNavigate={navigate}
                      onOpenConsegneAperte={openConsegneAperte}
                      onOpenConsegneFeed={() => openConsegneFeed()}
                      onSelectPaziente={goToPazienteByNome}
                      clinicalOverview={clinicalOverview}
                      clinicalOverviewState={clinicalOverviewState}
                      onRetryClinicalOverview={() => void loadClinicalOverview()}
                    />
                  )}
                  {!isAdmin && navKey === 'pazienti' && (
                    <PatientList
                      totalPatients={clinicalOverview?.totalPatients ?? 0}
                      ricerca={pazientiRicerca}
                      onRicercaChange={setPazientiRicerca}
                      filtroSesso={pazientiFiltroSesso}
                      onFiltroSessoChange={setPazientiFiltroSesso}
                      onSelect={selectPaziente}
                      operatorId={utente?.id}
                      operatorRole={utente?.ruolo}
                      onDeleted={(patientId) => {
                        setPazienteSelezionato((current) =>
                          current?.id === patientId ? null : current,
                        );
                      }}
                      onImported={(patientId, moduleTabId) => {
                        // La lista ricarica gia' la propria pagina. Per navigare a un paziente appena
                        // creato basta un lookup puntuale: non scaricare di nuovo l'intero roster.
                        if (!patientId) return;
                        const tab =
                          moduleTabId && MODULE_TAB_IDS.includes(moduleTabId as TabId)
                            ? (moduleTabId as TabId)
                            : undefined;
                        void selectPazienteById(patientId, tab);
                      }}
                    />
                  )}
                  {navKey === 'dettaglio-paziente' &&
                    !pazienteSelezionato &&
                    restoringPazienteFromHash && (
                      <div
                        style={{
                          padding: '48px 32px',
                          textAlign: 'center',
                          color: 'var(--text-muted)',
                        }}
                      >
                        <p style={{ fontSize: 16 }}>Caricamento scheda paziente…</p>
                      </div>
                    )}
                  {navKey === 'dettaglio-paziente' &&
                    !pazienteSelezionato &&
                    !restoringPazienteFromHash && (
                      <div
                        style={{
                          padding: '48px 32px',
                          textAlign: 'center',
                          color: 'var(--text-muted)',
                        }}
                      >
                        <p style={{ fontSize: 16, marginBottom: 16 }}>
                          Nessun paziente selezionato.
                        </p>
                        <button className="btn-primary" onClick={() => goBack('pazienti')}>
                          Vai alla lista pazienti
                        </button>
                      </div>
                    )}
                  {navKey === 'dettaglio-paziente' && pazienteSelezionato && (
                    <PatientDetail
                      key={pazienteSelezionato.id}
                      paziente={pazienteSelezionato}
                      cartella={getCartella(pazienteSelezionato.id)}
                      consegne={patientConsegne}
                      consegneSummary={patientConsegneSummary}
                      consegneLoading={loadingPatientConsegne}
                      consegneError={patientConsegneError}
                      consegneHasMore={patientConsegnePageInfo.hasMore}
                      onLoadMoreConsegne={() =>
                        void loadPatientConsegne(pazienteSelezionato.id, true)
                      }
                      onRetryConsegne={() => void loadPatientConsegne(pazienteSelezionato.id)}
                      operatori={operatori}
                      camere={camere}
                      camereLoadState={camereLoadState}
                      camereLoadError={camereLoadError}
                      onRetryCamere={() => void loadCamere(true, pazienteSelezionato.id)}
                      canAssignRooms
                      onBack={() => goBack('pazienti')}
                      backLabel={NAV_LABELS[prevNavKeyRef.current ?? 'pazienti']}
                      onAddConsegna={addConsegna}
                      consegnaDraftStore={consegnaDraftStore}
                      onUpdateConsegnaStato={updateConsegnaStato}
                      onUpdateCartella={updateCartella}
                      onUpdatePaziente={updatePaziente}
                      onAssignCamera={syncCameraAssignment}
                      operatoreNome={utente.nome}
                      operatoreId={utenteId}
                      initialTab={pendingModuleTab}
                      navigationRequestId={patientTabRequest}
                      assistantSectionRefresh={assistantSectionRefresh}
                      operatoreRole={utente?.ruolo}
                    />
                  )}
                  {!isAdmin && navKey === 'anagrafica-farmaci' && <AnagraficaFarmaciPage />}
                  {!isAdmin && navKey === 'parametri-multipaziente' && (
                    <MultiPatientParametri
                      key={utenteId}
                      operatoreNome={utente.nome}
                      onSelectPaziente={(patientId) =>
                        void selectPazienteById(patientId, 'parametri')
                      }
                    />
                  )}
                  {!isAdmin && navKey === 'agenda-operatore' && (
                    <OperatorAgenda
                      operatoreId={utenteId}
                      nomeOperatore={utente.nome}
                      operatori={operatori}
                      appuntamenti={appuntamenti}
                      onAddAppuntamento={addAppuntamento}
                      onUpdateAppuntamento={updateAppuntamento}
                      onDeleteAppuntamento={deleteAppuntamento}
                      loadingAppuntamenti={loadingAppuntamenti}
                      appointmentLoadError={appointmentLoadError}
                      onRetryAppointments={retryAppointmentRange}
                      onLoadAppointments={loadAppointmentRange}
                      onSelectPaziente={goToPazienteByNome}
                    />
                  )}
                </>
              )}
            </Suspense>
          </LazyLoadBoundary>
        </main>
      </div>

      {aiLoaded ? (
        <LazyLoadBoundary>
          <Suspense
            fallback={
              <button type="button" className="ai-fab" disabled aria-label="Caricamento assistente">
                <IcoAI />
              </button>
            }
          >
            <AgnosPanel
              openRequestId={aiOpenTrigger}
              forceOpen={aiOpen}
              onClose={() => setAiOpen(false)}
              operatorId={utente?.id}
              operatorRole={utente?.ruolo}
              operatorName={utente?.nome}
              currentPatientId={
                navKey === 'dettaglio-paziente' ? pazienteSelezionato?.id : navKey === 'consegne' && consegneMode === 'feed' ? consegneView.query?.patientId : undefined
              }
              currentPatientName={
                navKey === 'dettaglio-paziente' && pazienteSelezionato
                  ? `${pazienteSelezionato.lastName ?? ''} ${pazienteSelezionato.firstName ?? ''}`.trim()
                  : undefined
              }
              onExecuted={async (info) => {
                const sessionEpoch = sessionEpochRef.current;
                if (info.patientId) await loadCartella(info.patientId);
                if (sessionEpoch !== sessionEpochRef.current) return;
                setAssistantSectionRefresh((value) => ({
                  actionType: info.actionType ?? '',
                  version: value.version + 1,
                }));
                if (info.actionType === 'update_patient_demographics' && info.patientId) {
                  const patient = await fetchPatientById(API_URL, info.patientId, {
                    headers: operatorHeaders(),
                  });
                  if (sessionEpoch === sessionEpochRef.current) {
                    setPazienteSelezionato((current) =>
                      current?.id === patient.id ? patient : current,
                    );
                  }
                }
                // SPEC-015 US4: un'azione Agnos sull'agenda aggiorna subito la lista appuntamenti (FR-020)
                if (
                  info?.actionType === 'create_appointment' ||
                  info?.actionType === 'update_appointment'
                )
                  await loadAppuntamenti(appointmentRangeRef.current);
                // Agnos invalidates the same bounded feed/overview/patient read models as the UI.
                if (info?.actionType === 'create_consegna') refreshConsegnaViews();
              }}
              navKey={navKey}
              resolvePatientName={(id) => {
                const patient = pazienteSelezionato?.id === id ? pazienteSelezionato : null;
                return patient
                  ? `${patient.lastName ?? ''} ${patient.firstName ?? ''}`.trim()
                  : undefined;
              }}
              onNavigate={agnosNavigate}
            />
          </Suspense>
        </LazyLoadBoundary>
      ) : (
        <button
          type="button"
          className="ai-fab"
          onClick={openAiAssistant}
          aria-label="Assistente virtuale ClinicOS"
          title="Assistente virtuale ClinicOS"
        >
          <IcoAI />
        </button>
      )}
    </div>
    </RosterOrderContext.Provider>
  );
}

import { useEffect, useRef, useState } from 'react';
import type { FormEvent } from 'react';
import type { Operatore, Paziente, PrioritaConsegna } from '../../types';
import { IcoCheck, IcoX } from '../../icons';
import type { ConsegnaCreate } from '../../lib/consegnaCreation';
import { createConsegnaDraftStore, submitConsegna, type ConsegnaDraftStore, type ConsegnaFields } from '../../lib/consegnaDrafts';
import { useConsegnaDraft } from '../../lib/useConsegnaDraft';
import { PatientCombobox } from '../shared/PatientCombobox';
import './ConsegnaCreateForm.css';

interface ConsegnaCreateFormProps {
  operatori: Operatore[];
  isAdmin: boolean;
  onAdd: ConsegnaCreate;
  draftStore?: ConsegnaDraftStore;
  onClose: () => void;
}

const TIPO_OPTIONS = [
  'Monitoraggio',
  'Terapia',
  'Esami',
  'Dimissione',
  'Medicazione',
  'Consultazione',
  'Rivalutazione',
  'Altro',
];

export function ConsegnaCreateForm({
  operatori,
  onAdd,
  onClose,
  draftStore,
}: ConsegnaCreateFormProps) {
  const [patient, setPatient] = useState<Paziente | null>(null);
  const [store] = useState(() => draftStore ?? createConsegnaDraftStore());
  const draft = useConsegnaDraft(store, patient?.id ?? 'unselected');
  const form = draft.fields;
  const saving = draft.saving;
  const error = draft.outcome?.kind === 'failed' ? draft.outcome.message : null;
  const blocked = Boolean(draft.pending && draft.outcome?.kind === 'failed' && !draft.outcome.uncertain);
  const generation = useRef(0);
  useEffect(() => { generation.current++; return () => { generation.current++; }; }, [patient?.id]);
  useEffect(() => () => { if (!draftStore) store.clear(); }, [store, draftStore]);
  const setForm = (update: (current: ConsegnaFields) => ConsegnaFields) => store.update(patient?.id ?? 'unselected', update(form));
  const noteRef = useRef<HTMLTextAreaElement>(null);

  const canSubmit = Boolean(patient && form.note.trim() && form.scadenza && !saving && !blocked);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!patient || !form.note.trim() || saving) {
      if (!patient) document.getElementById('handover-patient')?.focus();
      else noteRef.current?.focus();
      return;
    }

    const token = store.begin(patient.id); if (!token) return;
    const version = generation.current;
    if (await submitConsegna(store, token, onAdd) && version === generation.current) onClose();
  }

  return (
    <form
      id="nuova-consegna-panel"
      className="op-form-panel handover-editor"
      aria-labelledby="new-handover-title"
      aria-busy={saving}
      onSubmit={submit}
    >
      <header className="op-form-panel__header handover-editor__header">
        <div>
          <span className="handover-editor__eyebrow">Passaggio operativo</span>
          <h3 id="new-handover-title" className="op-form-panel__title">
            Nuova consegna
          </h3>
          <p className="handover-editor__intro">
            Associa il paziente e indica con chiarezza cosa deve fare il prossimo operatore.
          </p>
        </div>
        <button
          type="button"
          className="icon-btn"
          aria-label="Chiudi nuova consegna"
          onClick={onClose}
          disabled={saving}
        >
          <IcoX />
        </button>
      </header>

      <div className="handover-editor__body">
        <fieldset className="handover-editor__section" disabled={saving || Boolean(draft.pending)}>
          <legend>Destinatario</legend>
          <div className="handover-editor__grid">
            <div className="handover-editor__field--patient">
              <PatientCombobox
                inputId="handover-patient"
                label="Paziente"
                selected={patient}
                onChange={setPatient}
                required
                disabled={saving}
                helperText="Sono disponibili i pazienti registrati nel tuo perimetro, con codice fiscale o data di nascita."
              />
            </div>
            {(
              <div className="form-field handover-editor__field--assignee">
                <label className="form-label" htmlFor="handover-assignee">
                  Assegna a
                </label>
                <select
                  id="handover-assignee"
                  name="operatoreAssegnatoId"
                  className="form-select"
                  value={form.operatoreAssegnatoId ?? ''}
                  onChange={(event) =>
                    setForm((current) => ({
                      ...current,
                      operatoreAssegnatoId: event.target.value,
                    }))
                  }
                  disabled={saving}
                >
                  <option value="">Non assegnata</option>
                  {operatori
                    .filter((operator) => operator.stato === 'attivo')
                    .map((operator) => (
                      <option key={operator.id} value={operator.id}>
                        {operator.cognome} {operator.nome}
                      </option>
                    ))}
                </select>
              </div>
            )}
          </div>
        </fieldset>

        <fieldset className="handover-editor__section" disabled={saving || Boolean(draft.pending)}>
          <legend>Dettagli operativi</legend>
          <div className="handover-editor__grid">
            <div className="form-field handover-editor__field--third">
              <label className="form-label" htmlFor="handover-type">
                Tipo
              </label>
              <select
                id="handover-type"
                name="tipo"
                className="form-select"
                value={form.tipo}
                onChange={(event) =>
                  setForm((current) => ({ ...current, tipo: event.target.value }))
                }
                disabled={saving}
              >
                {TIPO_OPTIONS.map((type) => (
                  <option key={type} value={type}>
                    {type}
                  </option>
                ))}
              </select>
            </div>
            <div className="form-field handover-editor__field--third">
              <label className="form-label" htmlFor="handover-priority">
                Priorità
              </label>
              <select
                id="handover-priority"
                name="priorita"
                className="form-select"
                value={form.priorita}
                onChange={(event) =>
                  setForm((current) => ({
                    ...current,
                    priorita: event.target.value as PrioritaConsegna,
                  }))
                }
                disabled={saving}
              >
                <option value="normale">Normale</option>
                <option value="alta">Alta</option>
                <option value="urgente">Urgente</option>
              </select>
            </div>
            <div className="form-field handover-editor__field--third">
              <label className="form-label" htmlFor="handover-date">
                Data scadenza
              </label>
              <input
                id="handover-date"
                name="scadenza"
                className="form-input"
                type="date"
                value={form.scadenza}
                onChange={(event) =>
                  setForm((current) => ({ ...current, scadenza: event.target.value }))
                }
                disabled={saving}
                required
              />
            </div>
            <div className="form-field handover-editor__field--third">
              <label className="form-label" htmlFor="handover-time">
                Ora scadenza <span className="handover-editor__optional-label">opzionale</span>
              </label>
              <input
                id="handover-time"
                name="oraScadenza"
                className="form-input"
                type="time"
                value={form.oraScadenza ?? ''}
                onChange={(event) =>
                  setForm((current) => ({ ...current, oraScadenza: event.target.value }))
                }
                disabled={saving}
              />
            </div>
          </div>
        </fieldset>

        <fieldset className="handover-editor__section handover-editor__section--last" disabled={saving || Boolean(draft.pending)}>
          <legend>Istruzioni</legend>
          <div className="form-field">
            <label className="form-label" htmlFor="handover-notes">
              Cosa deve essere fatto? <span aria-hidden="true">*</span>
            </label>
            <textarea
              ref={noteRef}
              id="handover-notes"
              name="note"
              className="form-input handover-editor__notes"
              rows={3}
              value={form.note}
              onChange={(event) => setForm((current) => ({ ...current, note: event.target.value }))}
              placeholder="Es. Controllare la pressione dopo cena e registrare il valore"
              maxLength={4000}
              disabled={saving}
              required
            />
            <span className="handover-editor__counter">{form.note.length}/4000</span>
          </div>
        </fieldset>
      </div>

      <footer className="op-form-panel__actions handover-editor__actions">
        {error ? (
          <p className="form-error handover-editor__error" role="alert">
            {error}
          </p>
        ) : (
          <p className="handover-editor__required-note">
            <span aria-hidden="true">*</span> Campi obbligatori
          </p>
        )}
        <button type="button" className="btn-secondary" onClick={onClose} disabled={saving}>
          Annulla
        </button>
        <button type="submit" className="btn-success" disabled={!canSubmit}>
          <IcoCheck /> {saving ? 'Creazione…' : draft.pending ? 'Riprova salvataggio' : 'Crea consegna'}
        </button>
      </footer>
    </form>
  );
}

import { useEffect, useRef, useState } from 'react';
import type { Operatore, Paziente } from '../../types';
import type { ConsegnaCreate } from '../../lib/consegnaCreation';
import { createConsegnaDraftStore, submitConsegna, type ConsegnaDraftStore } from '../../lib/consegnaDrafts';
import { ConsegnaComposer } from './ConsegnaComposer';
import './ConsegneRounds.css';
export function ConsegnaQuickAdd({ patient, operatori, onAdd, onClose, draftStore }: {
  patient: Paziente; operatori: Operatore[]; onAdd: ConsegnaCreate; onClose: () => void; draftStore?: ConsegnaDraftStore;
}) {
  const [store] = useState(() => draftStore ?? createConsegnaDraftStore()); const generation = useRef(0);
  useEffect(() => { generation.current++; return () => { generation.current++; }; }, [patient.id]);
  useEffect(() => () => { if (!draftStore) store.clear(); }, [store, draftStore]);
  async function save() {
    const token = store.begin(patient.id); if (!token) return;
    const version = generation.current;
    if (await submitConsegna(store, token, onAdd) && version === generation.current) onClose();
  }
  return <div className="handover-workspace"><ConsegnaComposer patient={patient} store={store} operatori={operatori} onSave={() => void save()} />
    <button type="button" className="link-btn" onClick={onClose}>Chiudi · conserva bozza</button></div>;
}

