                  </button>
                </div>
              )}
              {!consegneError && consegneLoading && mieConsegne.length === 0 ? (
                <p className="cr-empty" role="status">
                  Caricamento consegne…
                </p>
              ) : !consegneError && consegneSummary?.total === 0 ? (
                <p className="cr-empty">Nessuna consegna per questo paziente.</p>
              ) : !consegneError ? (
                <>
                  {consegneSummary && (
                    <p className="cr-empty" role="status">
